@Service
class BillingService {
    @Transactional
    public void process(Invoice i) {
        try {
            this.charge(i);
        } catch (RuntimeException e) {
            log.warn("charge failed", e);
        }
    }

    @Transactional
    public void charge(Invoice i) {
        invoiceRepo.save(i);
        throw new IllegalStateException("gateway down");
    }
}

interface Reporter {
    void run();
}

@Service
class DailyReporter implements Reporter {
    @Transactional
    public final void run() {
        rowRepo.save(new Row());
    }
}
